    art = ""
    for letter in word:
        size = random.choice(letter_sizes)
        art += "/" * size + "\n"
    return art


def generate_underline_font(word, letter_sizes):
    art = ""
    for letter in word:
        size = random.choice(letter_sizes)
        art += "_" * size + "\n"
    return art


