function subtractDates(date1, timeZone1, date2, timeZone2) {
  // Validate input formats
  const validDateFormat = /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/;
  const validTimeZoneFormat = /^(\+|-)\d{2}:\d{2}$/;

  if (!validDateFormat.test(date1) || !validDateFormat.test(date2)) {
    throw new Error("Invalid date format. Please use the format 'YYYY-MM-DD HH:MM:SS'");
  }

  if (!validTimeZoneFormat.test(timeZone1) || !validTimeZoneFormat.test(timeZone2)) {
    throw new Error("Invalid time zone format. Please use the format '+/-HH:MM'");
  }

  // Parse input dates and time zones
  const [year1, month1, day1, hours1, minutes1, seconds1] = date1.split(/[- :]/);
  const [year2, month2, day2, hours2, minutes2, seconds2] = date2.split(/[- :]/);

  const timeZoneOffset1 = parseTimeZoneOffset(timeZone1);
  const timeZoneOffset2 = parseTimeZoneOffset(timeZone2);

  // Convert dates to UTC
  const date1UTC = new Date(Date.UTC(year1, month1 - 1, day1, hours1, minutes1, seconds1) - timeZoneOffset1);
  const date2UTC = new Date(Date.UTC(year2, month2 - 1, day2, hours2, minutes2, seconds2) - timeZoneOffset2);

  // Calculate difference in milliseconds
  const difference = Math.abs(date1UTC - date2UTC);

  // Convert difference to hours, minutes, and seconds
  const hours = Math.floor(difference / 3600000);
  const minutes = Math.floor((difference % 3600000) / 60000);
  const seconds = Math.floor((difference % 60000) / 1000);

  return {
    hours,
    minutes,
    seconds
  };
}

function parseTimeZoneOffset(timeZone) {
  const sign = timeZone[0] === "+" ? 1 : -1;
  const [hours, minutes] = timeZone.slice(1).split(":").map(Number);
  return sign * (hours * 3600000 + minutes * 60000);
}
```

