  // Even numbers (except 2) are not prime
  if (number % 2 === 0) {
    return false;
  }

  // Check for divisibility by odd numbers from 3 up to the square root of the number
  for (let i = 3, sqrt = Math.sqrt(number); i <= sqrt; i += 2) {
