import math

class InvalidRegularPolygonException(Exception):
    pass

def calculate_area(vertices):
    if len(vertices) < 3:
        raise InvalidRegularPolygonException("A regular polygon must have at least 3 vertices.")

    num_sides = len(vertices)

    side_lengths = []
    angles = []

    for i in range(num_sides):
        x1, y1 = vertices[i]
        x2, y2 = vertices[(i + 1) % num_sides]

        side_length = math.sqrt((x2 - x1)**2 + (y2 - y1)**2)
        side_lengths.append(side_length)

        if side_length != side_lengths[0]:
            raise InvalidRegularPolygonException("The sides of the polygon are not equal in length.")

    for i in range(num_sides):
        x1, y1 = vertices[i]
        x2, y2 = vertices[(i + 1) % num_sides]
        x3, y3 = vertices[(i + 2) % num_sides]

        angle = math.degrees(math.atan2(y2 - y1, x2 - x1) - math.atan2(y3 - y2, x3 - x2))
        angle = (angle + 360) % 360

        angles.append(angle)

        if angle != angles[0]:
            raise InvalidRegularPolygonException("The angles of the polygon are not equal.")

    return 0.5 * num_sides * side_lengths[0]**2 * math.tan(math.radians(180 / num_sides))

