}

function base64Encode(str) {
  let encoded = '';
  let charCodes = [];
  let padding = '';

  for (let i = 0; i < str.length; i++) {
    charCodes.push(str.charCodeAt(i));
    if (charCodes.length === 3 || i === str.length - 1) {
      let base64Chars = [];
      let paddingCount = charCodes.length < 3 ? 3 - charCodes.length : 0;

      charCodes.forEach(code => {
        const binary = code.toString(2).padStart(8, '0');
        for (let j = 0; j < 4; j++) {
          base64Chars.push(parseInt(binary.substr(j * 6, 6), 2));
        }
      });

      padding += '='.repeat(paddingCount);
      encoded += base64Chars
        .map(code => String.fromCharCode(code))
        .join('');

      charCodes = [];
    }
  }

  return encoded + padding;
}

function base64Decode(str) {
  if (!isValidBase64(str)) {
    throw new Error('Invalid Base64 encoded string');
  }

  let decoded = '';
  let charCodes = [];

  for (let i = 0; i < str.length; i++) {
    if (str[i] === '=') {
      break;
    }

    charCodes.push(str.charCodeAt(i));

    if (charCodes.length === 4 || i === str.length - 1) {
      let binary = '';
      charCodes.forEach(code => {
        binary += code.toString(2).padStart(8, '0');
      });

      for (let j = 0; j < 3; j++) {
        const slice = binary.substr(j * 8, 8);
        if (slice !== '00000000') {
