```sql
DELIMITER //

CREATE PROCEDURE Subtract_Prime_Numbers(IN num1 INT, IN num2 INT, OUT result INT)
BEGIN
    DECLARE errorMsg VARCHAR(100);
    DECLARE isPrime1, isPrime2 BOOLEAN;

    IF num1 <= 0 OR num2 <= 0 THEN
        SET errorMsg = 'Error: Numbers should be greater than zero.';
        SELECT errorMsg;
        LEAVE;
    END IF;

    IF num1 > 1000 OR num2 > 1000 THEN
        SET errorMsg = 'Error: Numbers should not exceed 1000.';
        SELECT errorMsg;
        LEAVE;
    END IF;

    SET isPrime1 = TRUE;
    SET isPrime2 = TRUE;

    -- Check if num1 is prime
    IF num1 > 1 THEN
        DECLARE i INT DEFAULT 2;
        WHILE i <= SQRT(num1) DO
            IF num1 % i = 0 THEN
                SET isPrime1 = FALSE;
                LEAVE;
            END IF;
            SET i = i + 1;
        END WHILE;
    ELSE
        SET isPrime1 = FALSE;
    END IF;

    -- Check if num2 is prime
    IF num2 > 1 THEN
        DECLARE j INT DEFAULT 2;
        WHILE j <= SQRT(num2) DO
            IF num2 % j = 0 THEN
                SET isPrime2 = FALSE;
                LEAVE;
            END IF;
            SET j = j + 1;
        END WHILE;
    ELSE
        SET isPrime2 = FALSE;
    END IF;

    IF NOT isPrime1 OR NOT isPrime2 THEN
        SET errorMsg = 'Error: Numbers should be prime.';
        SELECT errorMsg;
        LEAVE;
    END IF;

    SET result = num1 - num2;
END //

DELIMITER ;
