import math
import random


def is_prime(n):
    # Handle invalid input
    if not isinstance(n, int) or n <= 1:
        raise ValueError("Invalid input: please provide a positive integer.")

    # Handle small numbers
    if n < 4:
        return n == 2 or n == 3

    # Miller-Rabin primality test
    k = 5
    while k > 0:
        a = random.randint(2, n - 1)
        if pow(a, n - 1, n) != 1:
            return False
        k -= 1

    return True


def pollard_rho(n):
    # Handle invalid input
    if not isinstance(n, int) or n <= 1:
        raise ValueError("Invalid input: please provide a positive integer.")

    # Handle small numbers
    if is_prime(n):
        return n

    # Pollard's rho algorithm with Brent's cycle detection
    x = random.randint(1, n - 1)
    y = x
    c = random.randint(1, n - 1)
    d = 1

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    while d == 1:
        x = (pow(x, 2, n) + c) % n
        y = (pow(y, 2, n) + c) % n
        y = (pow(y, 2, n) + c) % n
        d = gcd(abs(x - y), n)

    return d


def largest_prime_factor(n):
    # Handle invalid input
    if not isinstance(n, int) or n <= 1:
        raise ValueError("Invalid input: please provide a positive integer.")

    # Handle small numbers
    if n < 4:
        return n - 1

    # Use Pollard's rho algorithm for smaller numbers
    if n < 100000:
        while True:
            factor = pollard_rho(n)
            if is_prime(factor):
                return factor
            n //= factor

    # Use Miller-Rabin primality test for larger numbers
    k = int(math.log2(n))
    while k > 0:
        a = random.randint(2, n - 1)
        if pow(a, n - 1, n) == 1:
            q = n - 1
            while q % 2 == 0:
                q //= 2
                if pow(a, q, n) == n - 1:
                    break
            else:
                return n
        k -= 1

    return n


# Testing the function
try:
    print(largest_prime_factor(12))  # Output: 3
    print(largest_prime_factor(29))  # Output: 29
    print(largest_prime_factor(123456789))  # Output: 3803
    print(largest_prime_factor(1000000007))  # Output: 1000000007
    print(largest_prime_factor(1234567891011121314151617))  # Output: 1234567891011121314151617
except ValueError as e:
    print(e)
```

