// API endpoint
function sumOfEvenNumbers(req, res) {
  const inputArray = req.body.array;

  // Validate input array
  if (!Array.isArray(inputArray)) {
    return res.status(400).json({ error: 'Input must be an array' });
  }

  const length = inputArray.length;
  if (length < 1 || length > Math.pow(10, 6)) {
    return res.status(400).json({ error: 'Input array length must be between 1 and 10^6' });
  }

  // Calculate sum of even numbers
  let sum = 0;
  for (let i = 0; i < length; i++) {
    const num = inputArray[i];

    if (typeof num !== 'number') {
      return res.status(400).json({ error: 'Array elements must be numbers' });
    }

    if (num % 2 === 0) {
      sum += num;
    }
  }

  // Round sum to two decimal places
  sum = Math.round(sum * 100) / 100;

  res.json({ sum });
}

