import requests
import json
import time

class ExchangeRateCache:
    def __init__(self):
        self.cache = {}

    def get_exchange_rate(self, currency_pair):
        if currency_pair in self.cache:
            return self.cache[currency_pair]
        else:
            return None

    def set_exchange_rate(self, currency_pair, rate):
        self.cache[currency_pair] = rate

class ExchangeRateFetcher:
    def __init__(self, cache, api_url):
        self.cache = cache
        self.api_url = api_url
        self.max_retries = 3

    def fetch_exchange_rate(self, currency_pair):
        retries = 0
        while retries < self.max_retries:
            try:
                response = requests.get(self.api_url)
                if response.status_code == 200:
                    data = json.loads(response.text)
                    rate = data.get(currency_pair)
                    if rate is not None:
                        return rate
                else:
                    raise Exception(f"API returned status code: {response.status_code}")
            except Exception as e:
                print(f"Error occurred: {str(e)}")
                retries += 1
                time.sleep(1)

        return None

    def fetch_and_cache_exchange_rate(self, currency_pair):
        rate = self.fetch_exchange_rate(currency_pair)
        if rate is not None:
            self.cache.set_exchange_rate(currency_pair, rate)

    def periodically_fetch_and_cache_exchange_rates(self, currency_pairs, update_frequency):
        while True:
            for currency_pair in currency_pairs:
                self.fetch_and_cache_exchange_rate(currency_pair)
            time.sleep(update_frequency)

def main():
    cache = ExchangeRateCache()
    fetcher = ExchangeRateFetcher(cache, 'https://api.exchangeratesapi.io/latest')

    currency_pairs = ['USD/EUR', 'USD/GBP', 'USD/JPY'] # Example currency pairs
    update_frequency = 3600 # Update frequency in seconds (1 hour)

    # Start the periodic fetching and caching of exchange rates
    fetcher.periodically_fetch_and_cache_exchange_rates(currency_pairs, update_frequency)

    # Use the cache to get exchange rates
    usd_eur_rate = cache.get_exchange_rate('USD/EUR')
    if usd_eur_rate is not None:
        print(f"Current USD to EUR exchange rate: {usd_eur_rate}")

if __name__ == '__main__':
    main()
