Here is a JavaScript program that finds the greatest common divisor (GCD) of two given positive numbers, while also keeping track of the number of recursive calls made during the calculation:

```javascript
function gcd(x, y) {
  if (x < 0 || y < 0) {
    return "Error: Numbers must be positive.";
  } else if (x === 0 && y === 0) {
    return "Error: Numbers cannot both be zero.";
  } else if (x === 0) {
    return y;
  } else if (y === 0) {
    return x;
  } else {
    // Increment the recursive calls count
    gcd.calls++;

    // Use the Euclidean algorithm to find the GCD recursively
    return gcd(y, x % y);
  }
}

// Initialize the recursive calls count
