def postfix_to_infix(expression):
    stack = []
    for char in expression:
        if char.isdigit():
            stack.append(char)
        else:
            operand2 = stack.pop()
            operand1 = stack.pop()
            new_expression = '(' + operand1 + char + operand2 + ')'
            stack.append(new_expression)
    return stack.pop()

