  createUser: function(firstName, lastName, email, password) {
    if (this.isEmailUnique(email)) {
      const user = {
        firstName: firstName,
        lastName: lastName,
        email: email,
        password: password,
        username: this.generateUsername(firstName),
      };
      users.push(user);
      return user;
    } else {
      throw new Error('Email is already taken.');
    }
  },

  isEmailUnique: function(email) {
