  },

  validatePassword: function(password) {
    const lengthRegex = /.{15,}/;
    const uppercaseRegex = /(?=(.*[A-Z]){3,})/;
    const lowercaseRegex = /(?=(.*[a-z]){3,})/;
    const numberRegex = /(?=(.*\d){3,})/;
    const specialCharRegex = /(?=(.*[@#$%^&+=]){3,})/;
    const consecutiveRepeatingRegex = /(.)\1{1}/;

    return (
      lengthRegex.test(password) &&
      uppercaseRegex.test(password) &&
      lowercaseRegex.test(password) &&
      numberRegex.test(password) &&
      specialCharRegex.test(password) &&
      !consecutiveRepeatingRegex.test(password)
    );
  },

  generateUsername: function(firstName) {
    const alphanumericChars = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    let randomString = '';
    for (let i = 0; i < 5; i++) {
      const randomIndex = Math.floor(Math.random() * alphanumericChars.length);
      randomString += alphanumericChars.charAt(randomIndex);
    }
    return firstName + randomString;
  }
};
