Here's a JavaScript program that uses recursion to find the most commonly occurring item in a given object, considering that the object may contain nested objects. It handles the case where there are multiple items with the same highest frequency by returning an array of those items:

```javascript
function findMostCommonItem(obj) {
  let frequencyMap = {};

  function countItems(obj) {
    if (typeof obj === 'object' && obj !== null) {
      for (let key in obj) {
        countItems(obj[key]);
      }
    } else {
      frequencyMap[obj] = (frequencyMap[obj] || 0) + 1;
    }
  }

  countItems(obj);

  let maxFrequency = 0;
  let mostCommonItems = [];

  for (let item in frequencyMap) {
    if (frequencyMap[item] > maxFrequency) {
      maxFrequency = frequencyMap[item];
      mostCommonItems = [item];
    } else if (frequencyMap[item] === maxFrequency) {
      mostCommonItems.push(item);
    }
  }

  return mostCommonItems;
