            raise ValueError("Rating must be an integer between 1 and 5.")
        if not isinstance(user, User):
            raise ValueError("User object is required to add a rating.")
        if user.age < 18:
            raise ValueError("Only users who are at least 18 years old can add ratings.")
        if len(self.ratings) >= 100:
            return
        for r in self.ratings:
            if r["user"].name == user.name:
                return
        self.ratings.append({"rating": rating, "user": user})

    def get_ratings(self):
        return self.ratings

    def calculate_average_rating(self):
        if len(self.ratings) == 0:
            return 0
        total_ratings = 0
        for r in self.ratings:
            total_ratings += r["rating"]
        return round(total_ratings / len(self.ratings), 2)

    def calculate_weighted_average_rating(self):
        if len(self.ratings) == 0:
            return 0
        total_ratings = 0
        total_weight = 0
        for r in self.ratings:
            total_ratings += r["rating"] * len(self.ratings)
            total_weight += len(self.ratings)
        return round(total_ratings / total_weight, 2)

    def sort_ratings(self):
        self.ratings.sort(key=lambda x: x["rating"], reverse=True)

    @staticmethod
    def calculate_average_rating_per_genre(books):
        average_ratings = {}
        genre_ratings = {}
        for book in books:
            genre = book.genre
            if genre not in genre_ratings:
                genre_ratings[genre] = []
            genre_ratings[genre].extend(book.get_ratings())

        for genre, ratings in genre_ratings.items():
            total_ratings = 0
            total_books = 0
            for r in ratings:
                total_ratings += r["rating"]
                total_books += 1
            average_ratings[genre] = round(total_ratings / total_books, 2)

