        self.validate_matrix()
        transposed_matrix = [[self.matrix[j][i] for j in range(self.m)] for i in range(self.n)]
        return transposed_matrix

    def multiply_by_scalar(self, scalar):
        self.validate_matrix()
        multiplied_matrix = [[element * scalar for element in row] for row in self.matrix]
        return multiplied_matrix

    def add_matrices(self, other_matrix):
        if self.m != other_matrix.m or self.n != other_matrix.n:
            raise ValueError("Matrix dimensions are not compatible.")
        result_matrix = [[self.matrix[i][j] + other_matrix.matrix[i][j] for j in range(self.n)] for i in range(self.m)]
        return result_matrix

    def multiply_matrices(self, other_matrix):
        if self.n != other_matrix.m:
            raise ValueError("Matrix dimensions are not compatible.")
        result_matrix = [[sum(self.matrix[i][k] * other_matrix.matrix[k][j] for k in range(self.n)) for j in range(other_matrix.n)] for i in range(self.m)]
        return result_matrix

    def subtract_matrices(self, other_matrix):
        if self.m != other_matrix.m or self.n != other_matrix.n:
            raise ValueError("Matrix dimensions are not compatible.")
        result_matrix = [[self.matrix[i][j] - other_matrix.matrix[i][j] for j in range(self.n)] for i in range(self.m)]
        return result_matrix

    def calculate_determinant(self):
        self.validate_matrix()
        if self.m != self.n:
            raise ValueError("Matrix must be square.")
        if self.m == 1:
            return self.matrix[0][0]
        if self.m == 2:
            return self.matrix[0][0] * self.matrix[1][1] - self.matrix[0][1] * self.matrix[1][0]
        determinant = 0
        for j in range(self.n):
            submatrix = [[self.matrix[i][k] for k in range(self.n) if k != j] for i in range(1, self.m)]
            submatrix_obj = Matrix(self.m - 1, self.n - 1)
            submatrix_obj.matrix = submatrix
            determinant += ((-1) ** j) * self.matrix[0][j] * submatrix_obj.calculate_determinant()
        return determinant

