```javascript
function toCamelCase(str, ...excludedLists) {
  // Default list of excluded words
  const defaultExcludedWords = ['and', 'the', 'of'];

  // Merge all custom excluded word lists
  const excludedWords = excludedLists.reduce((acc, list) => acc.concat(list), defaultExcludedWords);

  // Remove leading and trailing spaces
  str = str.trim();

  // Remove consecutive spaces
  str = str.replace(/\s+/g, ' ');

  // Convert special characters and punctuation marks to spaces
  str = str.replace(/[^a-zA-Z0-9\u00C0-\u017F]+/g, ' ');

  // Split the string into words
  const words = str.split(' ');

  // Capitalize the first letter of each word (excluding excluded words)
  const camelCaseWords = words.map((word, index) => {
    if (index === 0) {
      return word.toLowerCase();
    } else if (!excludedWords.includes(word.toLowerCase())) {
      return word.charAt(0).toUpperCase() + word.slice(1).toLowerCase();
    } else {
      return word.toLowerCase();
    }
  });

  // Join the words and remove spaces
  const camelCaseStr = camelCaseWords.join('');

  return camelCaseStr;
}
```

