from collections import Counter

class ThreadSafeQueue:
    def __init__(self):
        self.queue = []
        self.lock = threading.Lock()

    def enqueue(self, element):
        with self.lock:
            if len(self.queue) >= 100:
                heapq.heappushpop(self.queue, element)
            else:
                heapq.heappush(self.queue, element)

    def dequeue(self):
        with self.lock:
            return heapq.heappop(self.queue)

    def is_empty(self):
        with self.lock:
            return len(self.queue) == 0

    def get_average(self):
        with self.lock:
            return statistics.mean(self.queue)

    def get_sum(self):
        with self.lock:
            return sum(self.queue)

    def get_median(self):
        with self.lock:
            return statistics.median(self.queue)

    def get_mode(self):
        with self.lock:
            counts = Counter(self.queue)
            mode = counts.most_common(1)[0][0]
            return mode

    def get_range(self):
        with self.lock:
            return max(self.queue) - min(self.queue)

    def get_standard_deviation(self):
        with self.lock:
            return statistics.stdev(self.queue)

    def get_variance(self):
        with self.lock:
            return statistics.variance(self.queue)

    def get_frequency_distribution(self):
        with self.lock:
            counts = Counter(self.queue)
            return counts

    def get_cumulative_sum(self):
        with self.lock:
            cum_sum = []
            total = 0
            for num in self.queue:
                total += num
                cum_sum.append(total)
            return cum_sum

    def get_cumulative_frequency_distribution(self):
        with self.lock:
            cum_freq_dist = {}
            counts = Counter(self.queue)
            total = 0
            for num, count in counts.items():
                total += count
                cum_freq_dist[num] = total
            return cum_freq_dist

    def get_interquartile_range(self):
        with self.lock:
            return statistics.quantiles(self.queue, n=4)[2] - statistics.quantiles(self.queue, n=4)[0]

    def get_kurtosis(self):
        with self.lock:
            return statistics.kurtosis(self.queue)

    def get_skewness(self):
        with self.lock:
            return statistics.skew(self.queue)

    def get_correlation_coefficient(self, x, y):
        with self.lock:
            return statistics.correlation(x, y)

    def get_covariance(self, x, y):
        with self.lock:
            return statistics.covariance(x, y)

    def get_probability_density_function(self, x):
        with self.lock:
            return statistics.pmf(self.queue, x)

    def get_cumulative_distribution_function(self, x):
        with self.lock:
            return statistics.cdf(self.queue, x)

    def get_z_score(self, x):
        with self.lock:
            return (x - statistics.mean(self.queue)) / statistics.stdev(self.queue)

    def get_percentile_rank(self, x):
        with self.lock:
            return statistics.percentileofscore(self.queue, x)

