import os
import subprocess

def create_virtual_environment(env_name):
    try:
        subprocess.check_call(['python', '-m', 'venv', env_name])
        print(f"Virtual environment '{env_name}' created successfully.")
    except subprocess.CalledProcessError:
        print(f"Failed to create virtual environment '{env_name}'.")
        return

def activate_virtual_environment(env_name):
    try:
        activate_script = os.path.join(env_name, 'Scripts', 'activate')
        subprocess.check_call([activate_script])
        print(f"Activated virtual environment '{env_name}'.")
    except subprocess.CalledProcessError:
        print(f"Failed to activate virtual environment '{env_name}'.")
        return

def check_package_installed(package, version=None):
    try:
        subprocess.check_output(['pip', 'show', package])
        print(f"Package '{package}' is already installed.")
        if version:
            upgrade_package(package, version)
    except subprocess.CalledProcessError:
        print(f"Package '{package}' is not installed.")
        install_package(package, version)

def install_package(package, version=None):
    try:
        if version:
            subprocess.check_call(['pip', 'install', f"{package}=={version}"])
            print(f"Package '{package}' version {version} installed successfully.")
        else:
            subprocess.check_call(['pip', 'install', package])
            print(f"Package '{package}' installed successfully.")
    except subprocess.CalledProcessError:
        print(f"Failed to install package '{package}'.")
        return

def upgrade_package(package, version=None):
    try:
        if version:
            subprocess.check_call(['pip', 'install', f"{package}=={version}", '--upgrade'])
            print(f"Package '{package}' upgraded to version {version} successfully.")
        else:
            subprocess.check_call(['pip', 'install', package, '--upgrade'])
            print(f"Package '{package}' upgraded successfully.")
    except subprocess.CalledProcessError:
        print(f"Failed to upgrade package '{package}'.")
        return

def uninstall_package(package):
    try:
        subprocess.check_call(['pip', 'uninstall', package, '-y'])
        print(f"Package '{package}' uninstalled successfully.")
    except subprocess.CalledProcessError:
        print(f"Failed to uninstall package '{package}'.")
        return

# Main script
def main():
    env_name = input("Enter the name of the virtual environment: ")
    create_virtual_environment(env_name)
    activate_virtual_environment(env_name)
    package = input("Enter the name of the package to install: ")
    version = input("Enter the version of the package (leave blank for latest version): ")
    check_package_installed(package, version)
    uninstall = input("Do you want to uninstall the package? (yes/no): ")
    if uninstall.lower() == 'yes':
        uninstall_package(package)

if __name__ == '__main__':
    main()

