import time

def get_valid_input():
    num_attempts = 0
    max_attempts = 5
    time_limit = 10 # seconds

    while num_attempts < max_attempts:
        num_attempts += 1
        try:
            start_time = time.time()
            user_input = int(input("Enter a valid positive integer between 1 and 1000 (inclusive): "))
            end_time = time.time()

            if 1 <= user_input <= 1000:
                print(f"Number of attempts: {num_attempts}")
                return user_input
            else:
                raise ValueError

        except ValueError:
            print("Invalid input. Please enter a valid positive integer between 1 and 1000 (inclusive).")

        except KeyboardInterrupt:
            print("\nYou have exceeded the time limit.")
            exit()

        except Exception as e:
            print("An unexpected error occurred:", str(e))
            exit()

        finally:
            if end_time - start_time > time_limit:
                print("\nYou have exceeded the time limit.")
                exit()

    print("You have reached the maximum number of attempts.")
    exit()

