  user: 'your_user',
  password: 'your_password'
};

// Create a new database connection
const db = pgp(dbConfig);

// Function to generate and persist a unique UUID
async function generateUniqueUUID() {
  let unique = false;
  let generatedUUID;

  while (!unique) {
    // Generate a new UUID in the required format
    generatedUUID = uuid.v4().replace(/-/g, '').replace(/(.{8})(.{4})(.{4})(.{4})(.{12})/, '$1-$2-4$3-y$4-$5');
    generatedUUID = generatedUUID.toLowerCase();

    try {
      // Start a transaction
      await db.tx(async (t) => {
        // Check if the generated UUID already exists in the database
        const existingUUID = await t.oneOrNone('SELECT id FROM uuid_table WHERE uuid = $1', [generatedUUID]);

        if (!existingUUID) {
          // Persist the generated UUID in the database
          await t.none('INSERT INTO uuid_table (uuid) VALUES ($1)', [generatedUUID]);
          unique = true;
        }
      });
    } catch (error) {
      console.error('Error generating unique UUID:', error);
    }
  }

  return generatedUUID;
}

// Generate a unique UUID
generateUniqueUUID()
  .then((uuid) => {
    console.log('Generated unique UUID:', uuid);
  })
  .catch((error) => {
    console.error('Error generating unique UUID:', error);
  });
```

