def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def square_numbers(lst):
    if not lst:
        print("Empty list")
        return

    squares = []
    total = 0
    for num in lst:
        if isinstance(num, int):
            if num % 2 == 0 and num < 10:
                if is_prime(num):
                    continue
                square = num**2
                squares.append(square)
                total += square
    print(','.join(map(str, squares)))
    print("Sum:", total)

