// Car object constructor
function Car(make, model, year, color, price, mileage) {
  this.make = make;
  this.model = model;
  this.year = year;
  this.color = color;
  this.price = price;
  this.mileage = mileage;
  this.drivenTimes = 0;
  this.totalDistance = 0;
