class Vehicle:
    color_options = ['red', 'blue', 'green', 'yellow', 'black']
    speed_limit_min = 0
    speed_limit_max = 300
    total_distance = 0

    def __init__(self, vehicle_type, make, model, year, speed, color):
        self.vehicle_type = vehicle_type
        self.make = make
        self.model = model
        self.year = year
        self._speed = speed
        self._color = color

    @property
    def speed(self):
        return self._speed

    @speed.setter
    def speed(self, value):
        if value < self.speed_limit_min or value > self.speed_limit_max:
            raise SpeedLimitError("Speed limit exceeded")
        self._speed = value

    @property
    def color(self):
        return self._color

    @color.setter
    def color(self, value):
        if value not in self.color_options:
            raise ValueError("Invalid color")
        self._color = value

    def accelerate(self, amount):
        new_speed = self.speed + amount
        self.speed = new_speed

    def brake(self, amount):
        new_speed = self.speed - amount
        self.speed = new_speed

    def calculate_distance(self, time):
        try:
            distance = self.speed * time / 3600
            rounded_distance = round(distance, 2)
            self.total_distance += rounded_distance
            return rounded_distance
        except ZeroDivisionError:
            return 0

    @classmethod
    def reset_total_distance(cls):
        cls.total_distance = 0


