        if id in self.data:
            raise ValueError("Entry with the same ID already exists")
        if len(self.data) >= 100:
            raise ValueError("Maximum capacity reached")

        # Data validation
        if not isinstance(id, int) or id <= 0:
            raise ValueError("ID must be a positive integer")
        if not isinstance(name, str) or len(name) > 50:
            raise ValueError("Name must be a string with max length of 50")
        if not isinstance(age, int) or age < 0 or age > 150:
            raise ValueError("Age must be an integer between 0 and 150")
        if gender not in ["Male", "Female", "Other"]:
            raise ValueError("Gender must be one of Male, Female, Other")
        if not isinstance(occupation, str) or len(occupation) > 100:
            raise ValueError("Occupation must be a string with max length of 100")

        self.data[id] = {
            "name": name,
            "age": age,
            "gender": gender,
            "occupation": occupation
        }

    def get_entry(self, id):
        if id not in self.data:
            raise ValueError("Entry with the specified ID does not exist")
        return self.data[id]

    def update_entry(self, id, **kwargs):
        if id not in self.data:
            raise ValueError("Entry with the specified ID does not exist")

        entry = self.data[id]
        for key, value in kwargs.items():
            if key not in entry:
