import React, { useState } from 'react';

const BlogPost = () => {
  const [likes, setLikes] = useState(0);
  const [comments, setComments] = useState([]);
  const [replyInputs, setReplyInputs] = useState({});
  const [editInputs, setEditInputs] = useState({});

