Here is the JavaScript function that checks if a number is prime or not:

```javascript
function isPrime(number) {
  // Check if the input is a positive integer
  if (!Number.isInteger(number) || number <= 0) {
    console.error("Input is not a positive integer");
    return;
  }

  // Check if the input is equal to 1
  if (number === 1) {
    return false;
  }

  // Iterate through all numbers from 2 to the square root of the input (rounded up)
  for (let i = 2; i <= Math.sqrt(number); i++) {
    // Check if i is a factor of the input
    if (number % i === 0) {
      return false;
    }
  }

  // No factors found, input is a prime number
  return true;
}

