import random
import string

def generate_password(length, special_chars=None, pattern=None):
    if length < 10 or length > 20:
        raise ValueError("Invalid password length. Length must be between 10 and 20 characters.")

    if special_chars is not None and not set(special_chars).issubset(string.punctuation):
        raise ValueError("Invalid special characters. Only special characters from '@#$%&*' are allowed.")

    if pattern is not None and not set(pattern).issubset(string.ascii_letters + string.digits + string.punctuation):
        raise ValueError("Invalid pattern. Only letters, digits, and special characters are allowed.")

    if pattern is not None and length != len(pattern):
        raise ValueError("Invalid pattern length. Length must match the password length.")

    if pattern is not None and len(set(pattern)) < len(pattern):
        raise ValueError("Invalid pattern. Pattern cannot contain repeated characters.")

    uppercase_letters = string.ascii_uppercase
    lowercase_letters = string.ascii_lowercase
    digits = string.digits
    if special_chars is None:
        special_chars = string.punctuation

    password = []
    if pattern is None:
        password.append(random.choice(uppercase_letters))
        password.append(random.choice(lowercase_letters))
        password.append(random.choice(digits))
        password.append(random.choice(special_chars))

        available_chars = uppercase_letters + lowercase_letters + digits + special_chars
        for _ in range(6, length):
            password.append(random.choice(available_chars))
    else:
        password = list(pattern)

    random.shuffle(password)

    password = ''.join(password)

    if password.count(string.ascii_uppercase) < 4 or password.count(string.digits) < 3 or password.count(special_chars) < 2:
        raise ValueError("Invalid password. Password does not meet additional requirements.")

    return password

