import math

def calculate_area(side1, side2, side3):
    if not is_valid_triangle(side1, side2, side3):
        return "Error: Invalid triangle"
    semi_perimeter = calculate_perimeter(side1, side2, side3) / 2
    area = math.sqrt(semi_perimeter * (semi_perimeter - side1) * (semi_perimeter - side2) * (semi_perimeter - side3))
    return round(area, 2)

def is_valid_triangle(side1, side2, side3):
    if side1 + side2 <= side3 or side1 + side3 <= side2 or side2 + side3 <= side1:
        return False
    return True

def calculate_perimeter(side1, side2, side3):
    return round(side1 + side2 + side3, 2)

def calculate_max_angle(side1, side2, side3):
    max_angle = math.acos((side1**2 + side2**2 - side3**2) / (2 * side1 * side2))
    return round(math.degrees(max_angle), 2)

def calculate_min_angle(side1, side2, side3):
    min_angle = math.acos((side1**2 + side3**2 - side2**2) / (2 * side1 * side3))
    return round(math.degrees(min_angle), 2)

def calculate_remaining_angle(side1, side2, side3):
    remaining_angle = math.acos((side2**2 + side3**2 - side1**2) / (2 * side2 * side3))
    return round(math.degrees(remaining_angle), 2)

def calculate_inscribed_circle_radius(area, semi_perimeter):
    radius = area / semi_perimeter
    return round(radius, 2)

def calculate_circumscribed_circle_radius(side1, side2, side3, area):
    radius = (side1 * side2 * side3) / (4 * area)
    return round(radius, 2)

