Here's an example JavaScript code that reads the content of a given URL, validates its format using regular expressions, and stores it in a MongoDB database. It also checks for specific keywords within the content and adds appropriate tags to the entries in the database. The code handles duplicate entries by updating the existing entry with the new data, implements a rate limit to prevent excessive requests, and performs all database operations asynchronously using promises.

```javascript
const axios = require('axios');
const mongoose = require('mongoose');

// Connect to MongoDB database
mongoose.connect('mongodb://localhost:27017/mydatabase', { useNewUrlParser: true, useUnifiedTopology: true });
const db = mongoose.connection;

// Create a schema for the data
const entrySchema = new mongoose.Schema({
  url: String,
  content: String,
  tags: [String]
});

// Create a model based on the schema
const Entry = mongoose.model('Entry', entrySchema);

// Define the URL to read and keywords to search for
const url = 'https://example.com';
const keywords = ['keyword1', 'keyword2'];

// Define rate limit variables
let lastRequestTime = null;
const REQUEST_INTERVAL = 5000; // 5 seconds

// Function to read the URL content, validate it, and store it in the database
async function readURLAndStoreContent() {
  // Check rate limit
  if (lastRequestTime && Date.now() - lastRequestTime < REQUEST_INTERVAL) {
    console.log('Rate limit exceeded. Skipping request.');
    return;
  }

  try {
    // Read URL content
    const response = await axios.get(url);
    const content = response.data;

    // Validate content format with regular expressions
    const isValidFormat = /<[^>]+>/.test(content); // Example validation using HTML tags

    if (isValidFormat) {
      // Check if the entry already exists in the database
      const existingEntry = await Entry.findOne({ url: url });

      if (existingEntry) {
        // Update existing entry with new data
        existingEntry.content = content;

        // Check for keywords and add tags
        existingEntry.tags = keywords.filter(keyword => content.includes(keyword));

        await existingEntry.save();
        console.log('Existing entry updated:', existingEntry);
      } else {
        // Create a new entry in the database
        const newEntry = new Entry({
          url: url,
          content: content,
          tags: keywords.filter(keyword => content.includes(keyword))
        });

        await newEntry.save();
        console.log('New entry created:', newEntry);
      }
    } else {
      console.log('Invalid content format. Skipping entry.');
    }

    // Update last request time
    lastRequestTime = Date.now();
  } catch (error) {
    console.error('Error reading URL:', error);
  }
}

// Call the function to read URL and store content
readURLAndStoreContent();
```

Please note that this code assumes you have installed the necessary dependencies (`axios` and `mongoose`) and have a running instance of MongoDB on `mongodb://localhost:27017/mydatabase`. You may need to modify the code according to your specific use case, such as adjusting the regular expression for content validation or changing the database connection URL.

