def combine_dicts(dict1, dict2):
    combined_dict = {}

    # Check if both dictionaries are empty
    if not dict1 and not dict2:
        return combined_dict

    for key, value in dict1.items():
        if key in dict2:
            if type(value) != type(dict2[key]):
                raise TypeError(f"Key '{key}' has different types in dict1 and dict2")
            elif isinstance(value, list):
                combined_dict[key] = value + dict2[key]
            elif isinstance(value, dict):
                combined_dict[key] = combine_dicts(value, dict2[key])
            else:
                combined_dict[key] = dict2[key]
        else:
            combined_dict[key] = value

    for key, value in dict2.items():
        if key not in dict1:
            combined_dict[key] = value

    return combined_dict
