        return self.height

    def setHeight(self, height):
        if height < 0 or height > 3:
            raise ValueError("Height should be between 0 and 3 meters.")
        self.height = height

    def getWeight(self):
        return self.weight

    def setWeight(self, weight):
        if weight < 0 or weight > 300:
            raise ValueError("Weight should be between 0 and 300 kilograms.")
        self.weight = weight

    def calculateBirthYear(self):
        current_year = datetime.datetime.now().year
        birth_year = current_year - self.age
