```python
class TelephoneDirectory:
    def __init__(self):
        self.entries = {}  # Dictionary to store entries
        self.prefixes = {}  # Dictionary to store prefixes

    def add_entry(self, name, phone_number):
        if phone_number in self.entries:
            raise ValueError("Phone number already exists.")

        self.entries[phone_number] = name
        self._update_prefixes(phone_number, True)

    def delete_entry(self, phone_number):
        if phone_number not in self.entries:
            raise ValueError("Phone number not found.")

        del self.entries[phone_number]
        self._update_prefixes(phone_number, False)

    def search(self, phone_number):
        if phone_number not in self.entries:
            raise ValueError("Phone number not found.")

        return self.entries[phone_number]

    def search_with_prefix(self, prefix):
        if prefix not in self.prefixes:
            return []

        return [self.entries[phone_number] for phone_number in self.prefixes[prefix]]

    def paginate_results(self, results, page_number, results_per_page):
        start_index = (page_number - 1) * results_per_page
        end_index = start_index + results_per_page
        return results[start_index:end_index]

    def _update_prefixes(self, phone_number, is_add):
        for i in range(1, len(phone_number) + 1):
            prefix = phone_number[:i]
            if is_add:
                if prefix not in self.prefixes:
                    self.prefixes[prefix] = []
                self.prefixes[prefix].append(phone_number)
            else:
                if prefix in self.prefixes:
                    self.prefixes[prefix].remove(phone_number)
                    if len(self.prefixes[prefix]) == 0:
                        del self.prefixes[prefix]
