```javascript
function generatePassword() {
  var characters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*';
  var password = '';
  var passwordLength = 12;
  var requiredChars = ['uppercase', 'lowercase', 'digit', 'special'];

  // Generate two characters for each required type
  for (var i = 0; i < requiredChars.length; i++) {
    var charType = requiredChars[i];
    var randomIndex = Math.floor(Math.random() * characters.length);
    password += characters[randomIndex];
  }

  // Generate remaining characters randomly
  for (var j = password.length; j < passwordLength; j++) {
    var randomIndex = Math.floor(Math.random() * characters.length);
    password += characters[randomIndex];
  }

  // Shuffle the password to avoid repeated characters
  password = shufflePassword(password);

  return password;
}

function shufflePassword(password) {
  var shuffledPassword = password.split('');
  var currentIndex = shuffledPassword.length;
  var temporaryValue, randomIndex;

  while (0 !== currentIndex) {
    randomIndex = Math.floor(Math.random() * currentIndex);
    currentIndex -= 1;

    temporaryValue = shuffledPassword[currentIndex];
    shuffledPassword[currentIndex] = shuffledPassword[randomIndex];
    shuffledPassword[randomIndex] = temporaryValue;
  }

  return shuffledPassword.join('');
}

