import sys
import requests
import time
import re
from collections import Counter

CACHE_DURATION = 24 * 60 * 60  # 24 hours in seconds
CACHE = {}

COMMON_WORDS = ["the", "and", "is", "in", "to", "a", "of", "that", "it", "as"]

def retrieve_text(url):
    try:
        response = requests.get(url)
        if response.status_code == 200:
            return response.text
        else:
            print(f"Error: Failed to retrieve content from {url}. Status code: {response.status_code}")
    except requests.exceptions.RequestException as e:
        print(f"Error: Failed to retrieve content from {url}. Exception: {e}")

def remove_punctuation(text):
    return re.sub(r'[^\w\s]', '', text)

def calculate_word_frequency(text, common_words):
    words = re.findall(r'\w+', text.lower())
    filtered_words = [word for word in words if word not in common_words]
    return Counter(filtered_words)

def display_word_frequency(word_frequency):
    print("Top 10 most frequently occurring words:")
    for word, frequency in word_frequency.most_common(10):
        print(f"{word}: {frequency}")

def is_cache_valid(url):
    if url in CACHE:
        timestamp, _ = CACHE[url]
        if time.time() - timestamp <= CACHE_DURATION:
            return True
    return False

def retrieve_word_frequency(url, common_words):
    if is_cache_valid(url):
        print("Retrieving word frequency from cache...")
        _, word_frequency = CACHE[url]
        return word_frequency
    else:
        print("Retrieving content from URL...")
        text = retrieve_text(url)
        if text:
            print("Calculating word frequency...")
            text = remove_punctuation(text)
            word_frequency = calculate_word_frequency(text, common_words)
            CACHE[url] = (time.time(), word_frequency)
            return word_frequency

def main():
    if len(sys.argv) < 2:
        print("Error: Please provide a URL as a command-line argument.")
        return
    url = sys.argv[1]
    common_words = COMMON_WORDS
    if len(sys.argv) > 2:
        common_words += sys.argv[2:]
    word_frequency = retrieve_word_frequency(url, common_words)
    display_word_frequency(word_frequency)

if __name__ == "__main__":
    main()
