Here's the script:

```javascript
const { performance } = require('perf_hooks');

// Function to check if a number is prime
const isPrime = (num) => {
  if (typeof num !== 'number' || isNaN(num)) {
    throw new Error('Invalid parameter: not a number');
  }

  if (num <= 1) {
    return false;
  }

  for (let i = 2; i <= Math.sqrt(num); i++) {
    if (num % i === 0) {
      return false;
    }
  }

  return true;
};

// Function to log a message based on the value of the parameter
const logMessage = (num) => {
  try {
    if (isPrime(num)) {
      console.log(`${num} is prime`);
    } else if (num > 0) {
      console.log(`${num} is positive`);
    } else if (num < 0) {
      console.log(`${num} is negative`);
    } else {
      console.log('Parameter is zero');
    }
  } catch (error) {
    console.error(`Error: ${error.message}`);
  }
};

// Loop to call the function with random numbers
const loop = async () => {
  const startTime = performance.now();
  let primeCount = 0;

  for (let i = 0; i < 1000; i++) {
    const randomNum = Math.floor(Math.random() * 201) - 100; // Generate random number between -100 and 100

    logMessage(randomNum);

    try {
      if (isPrime(randomNum)) {
        primeCount++;
      }
    } catch (error) {
      // Ignore errors for non-number parameters
    }
  }

  const endTime = performance.now();
  const executionTime = endTime - startTime;

  console.log(`\nPrime numbers encountered: ${primeCount}`);
  console.log(`Execution time: ${executionTime.toFixed(2)} ms`);
};

loop();
```

