def print_nested_dict(dictionary, indent='\t', separate_lines=True, include_quotes=False, max_width=80, max_depth=None, current_depth=0):
    if not isinstance(dictionary, dict):
        raise TypeError("Input is not a valid nested dictionary.")

    if max_depth is not None and current_depth > max_depth:
        print("Exceeded maximum nesting level.")
        return

    if current_depth == 0:
        dictionary = {k: v for k, v in sorted(dictionary.items())}

    for key, value in dictionary.items():
        if isinstance(value, dict):
            print(f"{indent * current_depth}{key}: dict")
            print_nested_dict(value, indent, separate_lines, include_quotes, max_width, max_depth, current_depth + 1)
        elif isinstance(value, list):
            print(f"{indent * current_depth}{key}: list")
            for item in value:
                if isinstance(item, (dict, list, tuple)):
                    print_nested_dict(item, indent, separate_lines, include_quotes, max_width, max_depth, current_depth + 1)
                else:
                    print(f"{indent * (current_depth + 1)}{item}: {type(item).__name__}")
        elif isinstance(value, tuple):
            print(f"{indent * current_depth}{key}: tuple")
            print_nested_dict(dict(enumerate(value)), indent, separate_lines, include_quotes, max_width, max_depth, current_depth + 1)
        else:
            if isinstance(value, str) and include_quotes:
                value_str = f"'{value}'"
            else:
                value_str = str(value)

            if len(value_str) > max_width:
                value_str = value_str[:max_width - 3] + '...'

            if separate_lines:
                print(f"{indent * current_depth}{key}: {value_str} ({type(value).__name__})")
            else:
                print(f"{indent * current_depth}{key}: {value_str} ({type(value).__name__})", end=' ')

    if current_depth == 0:
        print()
