Here's an example code snippet that demonstrates the implementation:

```javascript
// Function to generate a random key and IV using a cryptographically secure pseudo-random number generator
async function generateKeyAndIV() {
  const key = await crypto.subtle.generateKey({ name: 'AES-CBC', length: 256 }, true, ['encrypt', 'decrypt']);
  const iv = crypto.getRandomValues(new Uint8Array(16));

  return { key, iv };
}

// Function to encrypt the cookie value using AES encryption with a randomly generated key and IV
async function encryptCookieValue(cookieValue) {
  const { key, iv } = await generateKeyAndIV();
  const encodedKey = await crypto.subtle.exportKey('raw', key);

  const encodedCookieValue = new TextEncoder().encode(cookieValue);
  const encryptedValue = await crypto.subtle.encrypt({ name: 'AES-CBC', iv }, key, encodedCookieValue);
  const encodedEncryptedValue = Array.from(new Uint8Array(encryptedValue)).map(byte => String.fromCharCode(byte)).join('');

  const encodedIV = Array.from(iv).map(byte => String.fromCharCode(byte)).join('');

  // Store the key and IV securely, for example, as separate encrypted cookies or secure local storage
  document.cookie = `encryptedKey=${btoa(encodedKey)}`;
  document.cookie = `encryptedIV=${btoa(encodedIV)}`;

  // Return the base64 encoded encrypted cookie value
  return btoa(encodedEncryptedValue);
}

// Function to decrypt the cookie value using the same key and IV
async function decryptCookieValue(encryptedCookieValue) {
  const encodedEncryptedValue = atob(encryptedCookieValue);

  const encryptedValue = new Uint8Array(encodedEncryptedValue.length);
  for (let i = 0; i < encodedEncryptedValue.length; i++) {
    encryptedValue[i] = encodedEncryptedValue.charCodeAt(i);
  }

  const encodedKey = atob(getCookieValue('encryptedKey'));
  const encodedIV = atob(getCookieValue('encryptedIV'));

  const key = await crypto.subtle.importKey('raw', new Uint8Array(encodedKey), 'AES-CBC', true, ['decrypt']);
  const iv = new Uint8Array(encodedIV.length);
  for (let i = 0; i < encodedIV.length; i++) {
    iv[i] = encodedIV.charCodeAt(i);
  }

  const decryptedValue = await crypto.subtle.decrypt({ name: 'AES-CBC', iv }, key, encryptedValue);
  const decodedValue = new TextDecoder().decode(decryptedValue);

  return decodedValue;
}

// Helper function to retrieve cookie values
function getCookieValue(cookieName) {
  const name = cookieName + '=';
  const decodedCookie = decodeURIComponent(document.cookie);
  const cookieArray = decodedCookie.split(';');

  for (let i = 0; i < cookieArray.length; i++) {
    let cookie = cookieArray[i];
    while (cookie.charAt(0) === ' ') {
      cookie = cookie.substring(1);
    }
    if (cookie.indexOf(name) === 0) {
      return cookie.substring(name.length, cookie.length);
    }
  }

  return '';
}
```

