  const input = req.query.input;

  // Check if URL is present in cache
  const cachedUrl = cache.get(input);
  if (cachedUrl) {
    return res.json({ url: cachedUrl });
  }

  try {
    // Make API call to backend service to get the valid URL
    const response = await axios.get(`https://backend-service.com/validateUrl?input=${encodeURIComponent(input)}`);
    const data = response.data;

    if (data.valid) {
