      cache.set(input, data.url);

      return res.json({ url: data.url });
    } else {
      return res.status(400).json({ message: 'Invalid input' });
    }
  } catch (error) {
    return res.status(500).json({ message: 'An error occurred. Please try again later.' });
  }
});

