2. Start a loop from the first element to the second last element of the array.
3. Within the loop, start another loop from the first element to the second last element minus the current outer loop iteration count.
4. Within the second loop, compare each element with its adjacent element.
   a. If the adjacent element is greater than the current element, swap them.
   b. Update the "flag" variable to indicate that a swap has occurred.
5. After the completion of the inner loop, check the "flag" variable. If it is still "true", it means the array is already sorted, and we can terminate the outer loop.
6. If the "flag" variable is "false", continue to the next iteration of the outer loop.
7. After the completion of the outer loop, the array will be sorted in descending order.

Code:

function bubbleSortDescending(array) {
  let flag = true;

  for (let i = 0; i < array.length - 1; i++) {
    for (let j = 0; j < array.length - 1 - i; j++) {
      if (array[j] < array[j + 1]) {
        // Swap elements
        let temp = array[j];
        array[j] = array[j + 1];
        array[j + 1] = temp;

        // Update flag
        flag = false;
      }
    }

    // If array is already sorted, terminate
    if (flag) {
      break;
    }
  }

  return array;
}

