def get_current_datetime(timezone, language='english', include_seconds=True, date_format='mm/dd/yyyy'):
    try:
        tz = pytz.timezone(timezone)
    except pytz.UnknownTimeZoneError:
        raise ValueError("Invalid timezone")

    current_datetime = datetime.datetime.now(tz)

    # Handle daylight saving time
    is_dst = current_datetime.dst() != datetime.timedelta(0)

    # Handle different time formats
    time_format = "%H:%M:%S" if include_seconds else "%H:%M"
    if language.lower() == 'french':
        time_format = "%H:%M:%S" if include_seconds else "%H:%M"
    elif language.lower() == 'spanish':
        time_format = "%H:%M:%S" if include_seconds else "%I:%M %p"

    formatted_time = current_datetime.strftime(time_format)

    # Handle different date formats
    if date_format.lower() == 'mm/dd/yyyy':
        formatted_date = current_datetime.strftime("%m/%d/%Y")
    elif date_format.lower() == 'dd/mm/yyyy':
        formatted_date = current_datetime.strftime("%d/%m/%Y")
    else:
        raise ValueError("Invalid date format")

    return f"{formatted_date}, {formatted_time} {'DST' if is_dst else ''}"

