Rewrite the code such that it uses two semaphores, `semaphoreX` and `semaphoreY`, to synchronize access to the shared variables `x` and `y`, respectively. The program should ensure that only one thread can increment `x` at a time, and only one thread can increment `y` at a time, preventing race conditions.

```java
import java.util.concurrent.Semaphore;

public class ThreadSafeIncrement {
    private static int x = 0;
    private static int y = 0;
    private static Semaphore semaphoreX = new Semaphore(1);
    private static Semaphore semaphoreY = new Semaphore(1);

    public static void main(String[] args) {
        Thread t1 = new Thread(() -> {
            for (int i = 0; i < 100000; i++) {
                incrementX();
                incrementY();
            }
        });

        Thread t2 = new Thread(() -> {
            for (int i = 0; i < 100000; i++) {
                incrementX();
                incrementY();
            }
        });

        t1.start();
        t2.start();

        try {
            t1.join();
            t2.join();
        } catch (InterruptedException e) {
            e.printStackTrace();
        }

        System.out.println("Final value of x: " + x);
        System.out.println("Final value of y: " + y);
    }

    private static void incrementX() {
        try {
            semaphoreX.acquire();
            x++;
        } catch (InterruptedException e) {
            e.printStackTrace();
        } finally {
            semaphoreX.release();
        }
    }

    private static void incrementY() {
        try {
            semaphoreY.acquire();
            y++;
        } catch (InterruptedException e) {
            e.printStackTrace();
        } finally {
            semaphoreY.release();
        }
    }
}
