import { Component } from '@angular/core';

@Component({
  selector: 'checkout-component',
  template: `
    <h2>Product List</h2>
    <input type="text" [(ngModel)]="searchKeyword" placeholder="Search for products" (input)="searchProducts()">
    <ul>
      <li *ngFor="let product of filteredProducts">
        <img [src]="product.image" [alt]="product.name" />
        <h3>{{ product.name }}</h3>
        <p>{{ product.description }}</p>
        <p>Price: {{ product.price }}</p>
        <button (click)="addToCart(product)">Add to Cart</button>
      </li>
    </ul>

    <h2>Cart</h2>
    <ul>
      <li *ngFor="let item of cartItems">
        <img [src]="item.product.image" [alt]="item.product.name" />
        <h3>{{ item.product.name }}</h3>
        <p>Price: {{ item.product.price }}</p>
        <p>Quantity: <input type="number" [(ngModel)]="item.quantity" (input)="updateCart()"></p>
        <button (click)="removeFromCart(item)">Remove</button>
      </li>
    </ul>
    <p>Total Cost: {{ totalCost }}</p>

    <h2>Promo Code</h2>
    <input type="text" [(ngModel)]="promoCode" placeholder="Enter promo code">
    <button (click)="applyPromoCode()">Apply</button>
    <p *ngIf="promoCodeError">{{ promoCodeError }}</p>
    <p>Discounted Total Cost: {{ discountedTotalCost }}</p>

    <button (click)="checkout()" [disabled]="!canCheckout()">Proceed to Checkout</button>
  `
})
export class CheckoutComponent {
  products: any[] = [
    { name: 'Product 1', price: 10, description: 'Description 1', image: 'product1.jpg', stock: 5 },
    { name: 'Product 2', price: 20, description: 'Description 2', image: 'product2.jpg', stock: 10 },
    { name: 'Product 3', price: 30, description: 'Description 3', image: 'product3.jpg', stock: 3 }
  ];
  cartItems: any[] = [];
  totalCost: number = 0;
  searchKeyword: string = '';
  filteredProducts: any[] = [];
  promoCode: string = '';
  promoCodeError: string = '';
  discountedTotalCost: number = 0;

  addToCart(product: any) {
    if (product.stock > 0) {
      let cartItem = this.cartItems.find(item => item.product === product);
      if (cartItem) {
        if (cartItem.quantity < product.stock) {
          cartItem.quantity++;
        }
      } else {
        this.cartItems.push({ product: product, quantity: 1 });
      }
      product.stock--;
      this.updateCart();
    }
  }

  removeFromCart(item: any) {
    item.product.stock += item.quantity;
    this.cartItems = this.cartItems.filter(cartItem => cartItem !== item);
    this.updateCart();
  }

  updateCart() {
    this.totalCost = this.cartItems.reduce((sum, item) => sum + (item.product.price * item.quantity), 0);
  }

  searchProducts() {
    this.filteredProducts = this.products.filter(product =>
      product.name.toLowerCase().includes(this.searchKeyword.toLowerCase())
    );
  }

  applyPromoCode() {
    if (this.promoCode === 'CODE123') {
      // Additional conditions can be added here based on the promo code requirements
      this.discountedTotalCost = this.totalCost * 0.9; // 10% discount
      this.promoCodeError = '';
    } else {
      this.promoCodeError = 'Invalid promo code';
      this.discountedTotalCost = 0;
    }
  }

  canCheckout() {
    return this.totalCost > 0 && this.totalCost >= 50; // Minimum purchase amount of $50
  }

  checkout() {
    // Proceed to actual checkout process
  }
}
