def calculate_probability(probabilities):
    if any(prob < 0 for prob in probabilities):
        raise ValueError("Probabilities cannot be negative.")

    total_prob = 0
    favorable_prob = 0

    for i, prob in enumerate(probabilities):
        if prob == 0:
            continue

        total_prob += prob

        if i < len(probabilities) and i < 100:
            favorable_prob += prob

    return favorable_prob / total_prob

def calculate_mean(numbers):
    if not numbers:
        raise ValueError("List is empty")

    total = 0
    count = 0

    for num in numbers:
        if not isinstance(num, (int, float)):
            raise TypeError("List contains non-numeric values")
        total += num
        count += 1

    if count == 0:
        raise ValueError("List is empty")

    mean = total / count
    return round(mean, 2)

import math

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def is_perfect_square(n):
    sqrt = int(math.sqrt(n))
    return sqrt * sqrt == n

def sum_of_primes(n):
    primes = []
    for i in range(2, n + 1):
        if is_prime(i):
            primes.append(i)
    return sum(primes)

def product_of_primes(n):
    primes = []
    for i in range(2, n + 1):
        if is_prime(i):
            primes.append(i)
    product = 1
    for prime in primes:
        product *= prime
        if product > 10**12:
            return None
    return product

def main():
    num = int(input("Enter a number: "))
    print(f"Is {num} prime? {is_prime(num)}")

    print("Prime numbers between 2 and", num)
    for i in range(2, num + 1):
        if is_prime(i):
            print(i)

    if is_perfect_square(num):
        print(f"{num} is a perfect square")
    else:
        print(f"{num} is not a perfect square")

    print("Sum of prime numbers between 2 and", num, ":", sum_of_primes(num))

    product = product_of_primes(num)
    if product is None:
        print("Product of prime numbers exceeds the limit of the data type used for calculations.")
    else:
        print("Product of prime numbers between 2 and", num, ":", product)

if __name__ == "__main__":
    main()

