import sys

def get_valid_base(prompt):
    while True:
        base = input(prompt)
        try:
            base = int(base)
            if base < 2 or base > 36:
                print("Error: Base must be between 2 and 36")
            else:
                return base
        except ValueError:
            print("Error: Invalid base entered")

def get_valid_string(prompt, valid_digits):
    while True:
        string = input(prompt)
        if all(char in valid_digits for char in string):
            return string
        else:
            print("Error: Invalid characters in string")

def convert_number(string, current_base, desired_base):
    try:
        decimal_value = int(string, current_base)
        converted_string = ""
        while decimal_value > 0:
            remainder = decimal_value % desired_base
            converted_string = str(remainder) + converted_string
            decimal_value //= desired_base
        return converted_string
    except ValueError:
        print("Error: Invalid number or base")

def main():
    current_base = get_valid_base("Enter the current base (2-36): ")
    desired_base = get_valid_base("Enter the desired base (2-36): ")
    valid_digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"[:current_base]

    string = get_valid_string("Enter the string of numbers: ", valid_digits)

    converted_string = convert_number(string, current_base, desired_base)
    print("Converted number:", converted_string)

if __name__ == "__main__":
    main()
