def substitution_cipher(message, key):
    encrypted_message = ""
    for char in message:
        if char.isalpha():
            index = ord(char) - ord('A')
            encrypted_message += key[index]
        else:
            encrypted_message += char
    return encrypted_message

def transposition_cipher(message, key, block_size):
    blocks = [message[i:i+block_size] for i in range(0, len(message), block_size)]
    reordered_blocks = [blocks[int(i)-1] for i in key]
    encrypted_message = "".join(reordered_blocks)
    return encrypted_message

