import string

def caesar_cipher_encode(string, shift):
    encoded_string = ""
    for char in string:
        if char.isalpha():
            if char.islower():
                encoded_string += chr((ord(char) - ord('a') + shift) % 26 + ord('a'))
            else:
                encoded_string += chr((ord(char) - ord('A') + shift) % 26 + ord('A'))
        else:
            encoded_string += char
    return encoded_string

def caesar_cipher_decode(string, shift):
    return caesar_cipher_encode(string, -shift)

def get_valid_shift():
    while True:
        try:
            shift = int(input("Enter the shift value: "))
            if shift < 0 or shift > 25:
                print("Shift value must be between 0 and 25.")
                continue
            return shift
        except ValueError:
            print("Invalid shift value. Please enter an integer.")

def get_valid_string():
    while True:
        string = input("Enter the string: ")
        if not string.isalpha():
            print("String must contain only alphabetic characters.")
            continue
        return string

def menu():
