public class SumOfDigits {
    public static void main(String[] args) {
        long result = sumOfDigits(1234567890, 9876543210);
        System.out.println(result);
    }

    public static long sumOfDigits(long num1, long num2) {
        long sum = num1 + num2;

        if (sum > Long.MAX_VALUE || sum < Long.MIN_VALUE) {
            throw new IllegalArgumentException("Input values are outside the range of a 64-bit signed integer.");
        }

        long absSum = Math.abs(sum);
        long digitSum = 0;

        while (absSum != 0) {
            digitSum += absSum % 10;
            absSum /= 10;
        }

        return digitSum;
    }
}

