```typescript
import { Component, OnDestroy, OnInit } from '@angular/core';

@Component({
  selector: 'app-updating-variable',
  template: `
    <button (click)="toggleUpdate()">
      {{ updating ? 'Stop' : 'Resume' }}
    </button>
    <div *ngFor="let number of numbers">{{ number }}</div>
  `,
})
export class UpdatingVariableComponent implements OnInit, OnDestroy {
  numbers: number[] = [];
  updating = false;
  intervalId: any;

  ngOnInit() {
    this.startUpdating();
  }

  ngOnDestroy() {
    this.stopUpdating();
  }

  toggleUpdate() {
    if (this.updating) {
      this.stopUpdating();
    } else {
      this.startUpdating();
    }
  }

  startUpdating() {
    this.updating = true;
    this.intervalId = setInterval(() => {
      this.generateRandomNumbers();
    }, 1);
  }

  stopUpdating() {
    this.updating = false;
    clearInterval(this.intervalId);
  }

  generateRandomNumbers() {
    this.numbers = Array.from({ length: 1000000 }, () =>
      Math.floor(Math.random() * 1000000)
    );
  }
}
```

In this example, the `UpdatingVariableComponent` has an array `numbers` which holds the random numbers. The `updating` variable keeps track of whether the array should be updated or not. The `intervalId` is used to keep track of the interval.

The `ngOnInit` method initializes the component and starts the updating process. The `ngOnDestroy` method is used to clean up the interval when the component is destroyed.

