// Import the required modules
const MongoClient = require('mongodb').MongoClient;

// Connection URL
const url = 'mongodb://localhost:27017/';

// Database name
const dbName = 'university_db';

// Function to insert a new course record into the "courses" collection
const insertCourse = async (course) => {
  try {
    const client = await MongoClient.connect(url);
    const db = client.db(dbName);

    // Validate the input data
    validateCourse(course);

    // Check if the course name already exists
    const existingCourse = await db.collection('courses').findOne({ course_name: course.course_name });
    if (existingCourse) {
      throw new Error('Course name already exists!');
    }

    // Calculate the total number of students enrolled in each course
    course.students_enrolled = [];
    const students = await db.collection('students').find({}).toArray();
    for (const student of students) {
      if (isDateWithinRange(student.enrollment_date, course.start_date, course.end_date)) {
        course.students_enrolled.push(student.name);
      }
    }

    // Insert the new course record
    await db.collection('courses').insertOne(course);

    // Calculate the average GPA for each major and store it in the "major_statistics" collection
    const majorStatistics = await db.collection('major_statistics').find({}).toArray();
    for (const student of students) {
      const majorIndex = majorStatistics.findIndex(stat => stat.major === student.major);
      if (majorIndex !== -1) {
        majorStatistics[majorIndex].total_gpa += student.gpa;
        majorStatistics[majorIndex].total_students += 1;
      } else {
        majorStatistics.push({
          major: student.major,
          total_gpa: student.gpa,
          total_students: 1
        });
      }
    }

    for (const stat of majorStatistics) {
      stat.average_gpa = stat.total_gpa / stat.total_students;
      delete stat.total_gpa;
      delete stat.total_students;
    }

    await db.collection('major_statistics').deleteMany({});
    await db.collection('major_statistics').insertMany(majorStatistics);

    client.close();
  } catch (error) {
    console.error('Error:', error.message);
  }
};

// Function to validate the input data for a new course
const validateCourse = (course) => {
  if (course.course_name.trim() === '') {
    throw new Error('Course name cannot be empty!');
  }

  if (!/^[a-zA-Z]+$/.test(course.instructor)) {
    throw new Error('Instructor name can only contain alphabetic characters!');
  }

  const today = new Date().setHours(0, 0, 0, 0);
  if (course.start_date < today) {
    throw new Error('Start date cannot be in the past!');
  }

  if (course.end_date < course.start_date) {
    throw new Error('End date cannot be before the start date!');
  }

  if (course.students_enrolled.length === 0) {
    throw new Error('At least one student must be enrolled in the course!');
  }
};

