import re

def split_paragraph(paragraph):
    sentences = re.split(r'(?<!\w\.\w.)(?<![A-Z][a-z]\.)(?<=\.|\?)\s', paragraph)
    return sentences

def split_words(sentence):
    words = re.findall(r'\b\w+\b', sentence)
    return words

def remove_duplicates(words):
    unique_words = []
    for word in words:
        if word[0].lower() not in 'aeiou' and any(char.isdigit() or not char.isalnum() for char in word):
            if word not in unique_words:
                unique_words.append(word)
    return unique_words

def sort_words(words, ascending=True):
    return sorted(words, reverse=not ascending)

def display_words(words, uppercase=True):
    if uppercase:
        return [word.upper() for word in words]
    else:
        return [word.lower() for word in words]

def main():
    paragraph = input("Enter a paragraph: ")
    sentences = split_paragraph(paragraph)

    for sentence in sentences:
        words = split_words(sentence)
        unique_words = remove_duplicates(words)

        sort_option = input("Enter 'asc' for ascending or 'desc' for descending sort: ")
        if sort_option.lower() == 'desc':
            unique_words = sort_words(unique_words, ascending=False)
        else:
            unique_words = sort_words(unique_words, ascending=True)

        case_option = input("Enter 'upper' for uppercase or 'lower' for lowercase display: ")
        if case_option.lower() == 'lower':
            unique_words = display_words(unique_words, uppercase=False)
        else:
            unique_words = display_words(unique_words, uppercase=True)

        print("Unique words:", unique_words)

if __name__ == "__main__":
    main()
```

