def union_sets(s1, s2):
    # If both sets are empty, return an empty set
    if len(s1) == 0 and len(s2) == 0:
        return set()

    # If one of the sets is empty, return the other set
    if len(s1) == 0:
        return s2
    if len(s2) == 0:
        return s1

    # If the first element of the first set is smaller than the first element of the second set,
    # add it to the union set and recursively call the function with the remaining elements of the first set and the second set
    if s1[0] < s2[0]:
        return {s1[0]} | union_sets(s1[1:], s2)

    # If the first element of the second set is smaller than the first element of the first set,
    # add it to the union set and recursively call the function with the first set and the remaining elements of the second set
    if s2[0] < s1[0]:
        return {s2[0]} | union_sets(s1, s2[1:])

    # If the first elements of both sets are equal,
    # add the element to the union set and recursively call the function with the remaining elements of both sets
    return {s1[0]} | union_sets(s1[1:], s2[1:])

