Here's a JavaScript function that returns the kth greatest prime number from a given array of distinct numbers:

```javascript
function kthGreatestPrimeNumber(arr, k) {
  // Function to check if a number is prime
  function isPrime(num) {
    for (let i = 2, sqrt = Math.sqrt(num); i <= sqrt; i++) {
      if (num % i === 0) {
        return false;
      }
    }
    return num > 1;
  }

  // Use a min-heap to store the k greatest prime numbers
  const minHeap = [];

  // Add the first k elements to the min-heap
  for (let i = 0; i < k; i++) {
    const num = arr[i];
    if (isPrime(num)) {
      minHeap.push(num);
    }
  }

  // Convert the min-heap to a max-heap
  for (let i = Math.floor(k / 2) - 1; i >= 0; i--) {
    heapify(i);
  }

  // Process the remaining elements of the array
  for (let i = k; i < arr.length; i++) {
    const num = arr[i];
    if (isPrime(num) && num > minHeap[0]) {
      minHeap[0] = num;
      heapify(0);
    }
  }

  // Heapify a subtree rooted with node i
  function heapify(i) {
    const left = 2 * i + 1;
    const right = 2 * i + 2;
    let largest = i;

    if (left < k && minHeap[left] > minHeap[largest]) {
      largest = left;
    }

    if (right < k && minHeap[right] > minHeap[largest]) {
      largest = right;
    }

    if (largest !== i) {
      [minHeap[i], minHeap[largest]] = [minHeap[largest], minHeap[i]];
      heapify(largest);
    }
  }

  return minHeap[0];
}
```

