function multiply(x, y) {
  // Check if x and y are numbers
  if (typeof x !== 'number' || typeof y !== 'number') {
    return 'Invalid input: Both parameters should be numbers.';
  }

  // Check if x or y is negative
  if (x < 0 || y < 0) {
    return 'Negative numbers are not allowed.';
  }

  // Calculate the multiplication
  let result = x * y;

  // Check if the result exceeds the maximum allowed value for Number type
  if (result > Number.MAX_VALUE) {
    return 'Result is too large to be represented as a Number.';
  }

  // Check if x or y is floating-point number
  if (Number.isInteger(x) && Number.isInteger(y)) {
