import re

def evaluate_postfix(expression):
    stack = []
    operators = {
        '+': lambda a, b: a + b,
        '-': lambda a, b: a - b,
        '*': lambda a, b: a * b,
        '/': lambda a, b: a / b,
        '^': lambda a, b: a ** b,
        '%': lambda a, b: a % b
    }
    variables = {}

    def apply_operator(operator):
        b = stack.pop()
        a = stack.pop()
        result = operators[operator](a, b)
        stack.append(result)

    def evaluate_expression():
        for token in expression.split():
            if re.match(r'^-?\d+$', token):
                stack.append(int(token))
            elif re.match(r'^[a-zA-Z]$', token):
                if token not in variables:
                    variables[token] = int(input(f"Enter the value of {token}: "))
                stack.append(variables[token])
            elif token in operators:
                if len(stack) < 2:
                    raise ValueError("Not enough operands for operator")
                apply_operator(token)
            else:
                raise ValueError(f"Invalid character: {token}")

    try:
        evaluate_expression()
        if len(stack) != 1:
            raise ValueError("Invalid expression")
        return stack[0]
    except ValueError as e:
        return str(e)


expression = input("Enter a postfix expression: ")
result = evaluate_postfix(expression)
print(f"Result: {result}")
```

