import time
import math
import sys
import argparse


def fibonacci(n):
    memo = {}

    def fib_helper(n):
        if n in memo:
            return memo[n]
        elif n <= 1:
            return n
        else:
            memo[n] = fib_helper(n-1) + fib_helper(n-2)
            return memo[n]

    sequence = []
    for i in range(n+1):
        sequence.append(fib_helper(i))

    return sequence


def validate_positive_integer(number):
    try:
        number = int(number)
        if number <= 0:
            raise ValueError
    except ValueError:
        print("Please enter a positive integer.")
        sys.exit(1)
    return number


def save_to_file(sequence):
    filename = input("Enter the filename to save the Fibonacci sequence: ")
    with open(filename, 'w') as file:
        file.write(', '.join(map(str, sequence)))
    print("Fibonacci sequence saved to", filename)


def run_script():
    parser = argparse.ArgumentParser(description="Generate Fibonacci sequence up to a given number")
    parser.add_argument("numbers", metavar="N", type=str, nargs='+', help="positive integers for Fibonacci sequence")
    parser.add_argument("--save", action="store_true", help="save the Fibonacci sequence to a text file")
    args = parser.parse_args()

    for number in args.numbers:
        number = validate_positive_integer(number)

        start_time = time.time()
        sequence = fibonacci(number)
        end_time = time.time()

        execution_time = end_time - start_time
        print("Fibonacci sequence for", number, ": ", sequence)
        print("Execution time:", round(execution_time, 6), "seconds")

        if args.save:
            save_to_file(sequence)


