import datetime

class ScientificCalculator:
    def __init__(self):
        self.memory = []
        self.history = []

    def add(self, num1, num2):
        result = num1 + num2
        self._record_history("Addition", result)
        return result

    def subtract(self, num1, num2):
        result = num1 - num2
        self._record_history("Subtraction", result)
        return result

    def multiply(self, num1, num2):
        result = num1 * num2
        self._record_history("Multiplication", result)
        return result

    def divide(self, num1, num2):
        try:
            result = num1 / num2
            self._record_history("Division", result)
            return result
        except ZeroDivisionError:
            print("Error: Division by zero")
            return None

    def square_root(self, num):
        if num >= 0:
            result = num ** 0.5
            self._record_history("Square Root", result)
            return result
        else:
            print("Error: Square root of negative number")
            return None

    def power(self, base, exponent):
        result = base ** exponent
        self._record_history("Power", result)
        return result

    def factorial(self, num):
        if num < 0:
            print("Error: Factorial of a negative number")
            return None
        elif num == 0:
            return 1
        else:
            result = 1
            for i in range(1, num + 1):
                result *= i
            self._record_history("Factorial", result)
            return result

    def complex_add(self, num1_real, num1_imaginary, num2_real, num2_imaginary):
        result_real = num1_real + num2_real
        result_imaginary = num1_imaginary + num2_imaginary
        self._record_history("Complex Addition", f"{result_real} + {result_imaginary}i")
        return result_real, result_imaginary

    def complex_subtract(self, num1_real, num1_imaginary, num2_real, num2_imaginary):
        result_real = num1_real - num2_real
        result_imaginary = num1_imaginary - num2_imaginary
        self._record_history("Complex Subtraction", f"{result_real} + {result_imaginary}i")
        return result_real, result_imaginary

    def complex_multiply(self, num1_real, num1_imaginary, num2_real, num2_imaginary):
        result_real = (num1_real * num2_real) - (num1_imaginary * num2_imaginary)
        result_imaginary = (num1_real * num2_imaginary) + (num1_imaginary * num2_real)
        self._record_history("Complex Multiplication", f"{result_real} + {result_imaginary}i")
        return result_real, result_imaginary

    def complex_divide(self, num1_real, num1_imaginary, num2_real, num2_imaginary):
        denominator = (num2_real ** 2) + (num2_imaginary ** 2)
        if denominator != 0:
            result_real = ((num1_real * num2_real) + (num1_imaginary * num2_imaginary)) / denominator
            result_imaginary = ((num1_imaginary * num2_real) - (num1_real * num2_imaginary)) / denominator
            self._record_history("Complex Division", f"{result_real} + {result_imaginary}i")
            return result_real, result_imaginary
        else:
            print("Error: Division by zero in complex division")
            return None

    def store_memory(self, num):
        self.memory.append(num)

    def recall_memory(self, index):
        if index >= 0 and index < len(self.memory):
            return self.memory[index]
        else:
            print("Error: Memory index out of range")
            return None

    def _record_history(self, operation, result):
        timestamp = datetime.datetime.now()
        entry = {
            "timestamp": timestamp,
            "operation": operation,
            "result": result
        }
        self.history.append(entry)

    def view_history(self):
        for entry in self.history:
            print(f"{entry['timestamp']}: {entry['operation']} = {entry['result']}")

    def search_history(self, operation):
        matches = []
        for entry in self.history:
            if entry['operation'] == operation:
                matches.append(entry)
        return matches

    def export_history(self, filename):
        try:
            with open(filename, "w") as file:
                for entry in self.history:
                    file.write(f"{entry['timestamp']}: {entry['operation']} = {entry['result']}\n")
        except IOError:
            print("Error: Failed to export history to file")
