```javascript
function validateCreditCardNumber(creditCardNumber) {
  // Error handling
  if (typeof creditCardNumber !== 'string' || creditCardNumber.length === 0) {
    throw new Error('Invalid input: credit card number must be a non-empty string');
  }

  if (!/^\d+$/.test(creditCardNumber)) {
    throw new Error('Invalid input: credit card number must only contain digits');
  }

  if (creditCardNumber.length < 13 || creditCardNumber.length > 19) {
    throw new Error('Invalid input: credit card number length should be between 13 and 19 digits');
  }

  // Luhn algorithm implementation
  let sum = 0;
  let isSecondDigit = false;

  for (let i = creditCardNumber.length - 1; i >= 0; i--) {
    let digit = Number(creditCardNumber.charAt(i));

    if (isSecondDigit) {
      digit *= 2;
      if (digit > 9) {
        digit -= 9;
      }
    }

    sum += digit;
    isSecondDigit = !isSecondDigit;
  }

  return sum % 10 === 0;
}

