```javascript
function validateCreditCardNumberErroneous(creditCardNumber) {
  let sum = 0;

  for (let i = 0; i < creditCardNumber.length; i++) {
    let digit = Number(creditCardNumber.charAt(i));
    sum += digit;
  }

  return sum % 10 === 0;
